update pages set contenu = '{"sections":[{"type":"heros","h1":"Contrat de maintenance","mecanisme":"L''abonnement Zéro arrêt remplace vos dépannages subis par un programme de visites préventives, un suivi de l''état du parc et une priorité d''intervention. Le prix est fixe et connu d''avance.","cta":"Lancer mon diagnostic gratuit","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option."},{"type":"chiffres","chiffres":[{"valeur":"+ 80","libelle":"clients réguliers, la preuve qu''un contrat se renouvelle"},{"valeur":"10 %","libelle":"des candidats retenus, chaque technicien qui passe chez vous est évalué"}]},{"type":"probleme","punchline":"Arrêtez de payer des dépannages. Au troisième dépannage dans l''année, nos équipes le constatent sur le terrain : vous avez déjà financé un contrat annuel.","puces":[{"accroche":"Le tarif se négocie machine à l''arrêt.","texte":"Personne ne fait un bon achat un vendredi à 16h avec une ligne bloquée."},{"accroche":"Le technicien repart de zéro à chaque fois.","texte":"Aucun historique, aucune connaissance du parc, le diagnostic se repaie intégralement."},{"accroche":"La panne revient.","texte":"On traite le symptôme, jamais la cause racine, et la même machine retombe en panne deux mois plus tard."},{"accroche":"Le budget de maintenance échappe à tout pilotage.","texte":"Vous le constatez en fin d''exercice, vous ne le décidez pas en début d''année."}]},{"type":"offre","lignes":[{"prestation":"**Un plan de maintenance préventive construit sur votre parc réel** : inventaire, points critiques, programme de visites, contrôles, graissage, réglages, remplacements périodiques.","benefice":"Les défaillances sont anticipées au lieu d''être découvertes. Les arrêts deviennent planifiés."},{"prestation":"**La priorité d''intervention en cas de panne**, dans les conditions de délai prévues au contrat.","benefice":"Votre demande n''attend pas qu''un technicien se libère. Elle passe devant les demandes ponctuelles."},{"prestation":"**Un technicien qui connaît déjà votre site** à chaque passage.","benefice":"Le temps de prise en main disparaît de la facture et de la durée d''arrêt."},{"prestation":"**Le suivi de l''état des installations** : historique, mesures relevées, recommandations, inspections réglementaires.","benefice":"Vos décisions d''investissement et de renouvellement s''appuient sur des données, pas sur une impression."},{"prestation":"**Un référent technique dédié**, joignable entre deux visites.","benefice":"Pas de plateforme anonyme. Une question technique trouve une réponse rapide."},{"prestation":"**Trois niveaux de couverture** : base préventive, couverture complète, couverture étendue avec astreinte ou volume d''heures d''amélioration.","benefice":"Vous payez ce que votre équipe interne ne couvre pas, au lieu d''un forfait uniforme."},{"prestation":"**Pas de marge cachée sur les pièces** : nous consultons le marché fournisseur pour vous, notre société ne vit pas de la vente de pièces.","benefice":"La recommandation de remplacement est indépendante de ce qu''elle nous rapporterait."}],"prose":[{"texte":"Besoin d''une intervention ponctuelle avant d''envisager un contrat ? Voir le [dépannage industriel](/offres/depannage-industriel/). Migen est une [entreprise de maintenance industrielle](/offres/) présente partout en France."}]},{"type":"deroule","etapes":[{"titre":"Le diagnostic gratuit","texte":"vous remplissez le questionnaire, quelques minutes suffisent, ou vous appelez le 04 78 33 72 05. Aucune contrepartie attendue."},{"titre":"L''audit sur site","texte":"un référent technique visite vos installations, fait l''inventaire et analyse vos historiques de pannes et d''entretien."},{"titre":"Le calcul face à vos chiffres","texte":"nous additionnons vos douze derniers mois, factures de dépannage, heures de production perdues et temps passé par vos équipes. Ce total est mis en face du montant de l''abonnement."},{"titre":"La recommandation honnête","texte":"si un abonnement complet ne se justifie pas pour votre site, nous vous le disons et nous proposons le niveau qui convient."},{"titre":"La proposition","texte":"périmètre, programme de visites, niveaux de service, tarif. Chaque clause se lit sans avocat."},{"titre":"Le démarrage","texte":"la première visite pose l''état des lieux de référence. Les suivantes déroulent le programme, et les résultats se mesurent : nombre d''incidents, disponibilité, budget tenu."}]},{"type":"garanties","puces":[{"accroche":"Un prix fixe connu d''avance","texte":"le montant de l''abonnement ne bouge pas en cours de période. Les pièces majeures et les travaux exceptionnels sont chiffrés à part, définis noir sur blanc à la signature."},{"accroche":"Des résultats mesurés, pas affirmés","texte":"nombre d''incidents, disponibilité des équipements, budget tenu. Le programme s''ajuste chaque année sur ces mesures, et l''engagement de 6 mois renouvelable nous oblige à les prouver."},{"accroche":"Des attestations transmises, pas des logos","texte":"démarche MASE pour la sécurité des interventions, évaluation EcoVadis pour la performance RSE. Les attestations partent avec chaque plan de prévention, et les habilitations des techniciens qui entrent sur votre site sont à jour."}]},{"type":"cta","question":"Besoin de savoir si un abonnement vous coûterait moins cher que vos pannes de l''an dernier ?","bouton":"Lancer mon diagnostic gratuit","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Contrat de maintenance préventive annuelle sur des sites logistiques","texte":"six techniciens polyvalents en permanence, depuis septembre 2023","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Maintenance sous contrat d''un parc déployé partout en France, réalité virtuelle","texte":"depuis février 2024","lienLibelle":"Étude de cas TIMESCOPE : casques de réalité virtuelle","lienHref":"/preuves/timescope/"},{"titre":"Maintenance préventive et curative d''une fonderie","texte":"depuis octobre 2023, aux côtés des équipes internes","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Maintien opérationnel des équipements d''un site, logistique et transport","texte":"deux techniciens en poste","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Contrat de maintenance sur un site agroalimentaire de grande échelle, Belgique","texte":"depuis octobre 2024, toujours en cours","lienLibelle":"Étude de cas McCAIN : Belgique","lienHref":"/preuves/mccain-belgique/"}]},{"type":"objections","questions":[{"question":"Combien coûte l''abonnement ?","reponse":"Le montant est établi sur devis, après le diagnostic de vos installations. Il dépend du nombre d''équipements couverts, de la fréquence des visites, des niveaux de service retenus et du volume d''heures inclus. Le diagnostic qui produit ce chiffrage est gratuit, et il vous reste même si vous ne signez pas."},{"question":"Sur quelle durée s''engage-t-on ?","reponse":"L''engagement type est de 6 mois renouvelable. Les conditions de reconduction et de résiliation sont écrites en clair : pas de reconduction piégée, pas de préavis caché. Six mois, c''est assez long pour que la baisse du nombre d''incidents soit mesurable et assez court pour que nous ayons à la démontrer."},{"question":"Nous avons déjà un contrat ailleurs. Comment on bascule ?","reponse":"Nous préparons la reprise pendant le préavis de votre contrat en cours : inventaire du parc, récupération des historiques et des gammes, reprise du calendrier de visites."},{"question":"Qui répond de la sécurité pendant les visites ?","reponse":"Plan de prévention, accueil sécurité, habilitations à jour, respect des consignations et des règles d''accès de votre site. Le contrat précise les obligations de chaque signataire en matière de sécurité et un article dédié à la confidentialité des données techniques."},{"question":"Qui intervient sur nos machines ?","reponse":"Des techniciens Migen, évalués en entretien technique et comportemental, 10 % des candidats retenus. Sous contrat, c''est le même technicien qui revient : il connaît vos équipements, vos accès et vos contraintes. Toutes les expertises sont mobilisables, mécanique, électricité, automatisme, hydraulique, pneumatique."},{"question":"Couvrez-vous notre région, et les petits sites ?","reponse":"Oui aux deux. Nous travaillons depuis 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France. Un atelier avec cinq machines critiques justifie un contrat léger mais réel : le programme est dimensionné sur votre réalité, pas sur un catalogue."}]},{"type":"ctaFinal","question":"Besoin d''un budget de maintenance que vous connaissez en janvier plutôt qu''en décembre ?","bouton":"Lancer mon diagnostic gratuit"}]}'::jsonb where path = '/offres/zero-arret/';
